description:
Implement a hook that runs a callback on every animation frame using `requestAnimationFrame`. Returns `{ start, stop, isRunning }`. The loop continues until `stop()` is called or the component unmounts.

**Example:**
```tsx
const { start, stop, isRunning } = useAnimationFrame((time) => {
  setAngle(time * 0.001);
});
```

starter_code:
import { useRef, useState, useCallback, useEffect } from 'react';

export function useAnimationFrame(callback: (time: number) => void) {
  // your code here
}

test_suite:
test('starts not running', () => {
  const { result } = renderHook(() => useAnimationFrame(vi.fn()));
  expect(result.current.isRunning).toBe(false);
});

test('start sets isRunning to true', () => {
  const { result } = renderHook(() => useAnimationFrame(vi.fn()));
  act(() => result.current.start());
  expect(result.current.isRunning).toBe(true);
});

test('stop sets isRunning to false', () => {
  const { result } = renderHook(() => useAnimationFrame(vi.fn()));
  act(() => result.current.start());
  act(() => result.current.stop());
  expect(result.current.isRunning).toBe(false);
});

test('requestAnimationFrame is called after start', () => {
  const rafSpy = vi.spyOn(globalThis, 'requestAnimationFrame').mockReturnValue(1 as any);
  const { result } = renderHook(() => useAnimationFrame(vi.fn()));
  act(() => result.current.start());
  expect(rafSpy).toHaveBeenCalled();
  act(() => result.current.stop());
  rafSpy.mockRestore();
});

// __hidden__
test('cancelAnimationFrame is called on stop', () => {
  const cafSpy = vi.spyOn(globalThis, 'cancelAnimationFrame').mockImplementation(() => {});
  vi.spyOn(globalThis, 'requestAnimationFrame').mockReturnValue(42 as any);
  const { result } = renderHook(() => useAnimationFrame(vi.fn()));
  act(() => result.current.start());
  act(() => result.current.stop());
  expect(cafSpy).toHaveBeenCalledWith(42);
  cafSpy.mockRestore();
});

solution:
import { useRef, useState, useCallback, useEffect } from 'react';

export function useAnimationFrame(callback: (time: number) => void) {
  const [isRunning, setIsRunning] = useState(false);
  const rafRef = useRef<number | null>(null);
  const callbackRef = useRef(callback);

  useEffect(() => { callbackRef.current = callback; }, [callback]);

  const stop = useCallback(() => {
    setIsRunning(false);
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
  }, []);

  const start = useCallback(() => {
    setIsRunning(true);
    const loop = (time: number) => {
      callbackRef.current(time);
      rafRef.current = requestAnimationFrame(loop);
    };
    rafRef.current = requestAnimationFrame(loop);
  }, []);

  useEffect(() => () => { if (rafRef.current !== null) cancelAnimationFrame(rafRef.current); }, []);

  return { start, stop, isRunning };
}
